#!/usr/bin/env python3
"""Autorenwerkzeug: Johannesevangelium Kapitel 8–14 – Befunde, Deutungen, Grundsätze, Anwendungen, offene Fragen,
Beziehungen, Hintergrund zu Abschnitten, Kapitel-Zusammenfassungen und Studie; jeweils mit Züridüütsch-Lokalisierung.

Abgrenzung: Hintergrund zum ganzen Buch steht in BG-JHN-BOOK-0001/-0002 (Lieblingsjünger und Gemeinde; Verhältnis zu
den anderen Evangelien) und wird hier nicht wiederholt. Nummernbereich dieser Datei: 2001–2999. Der Kontext
CTX-JHN-READERS-0095 wird nur verwendet, nie geschrieben: run() liest ihn aus der Datei und gibt ihn unverändert weiter,
sodass _lib.write nichts ändert. Für die Zeit Jesu wird der bestehende Kontext CTX-GALILEE-0030 (Galiläa/Judäa um 30)
verwendet.

Abschnitte: Jede Aussage nennt den Versbereich, auf den sie sich bezieht; zugeordnet wird die kleinste vorhandene
Texteinheit (data/text-units/TU-JHN-…), die ihn ganz enthält, sonst die Kapiteleinheit.
Zählungen: nach den MACULA-Lemmata zum SBLGNT (data/annotations/MACULA-SBLGNT-JHN-0nn.json); der SBLGNT-Token-Text
enthält [[JHN.7.53-JHN.8.11]] (in Doppelklammern). Die Wortfolge ἐγώ εἰμι ist als unmittelbare Folge der Lemmata
ἐγώ (Form ἐγώ) und εἰμί gezählt.
Handschriftenangaben: aus den CNTR-Transkriptionen (data/witness-texts/CNTR-GA…-JHN.json), maschinell gelesen, nicht
am Faksimile geprüft.

Aufruf: python3 scripts/authoring/johannes_study_b.py
KI-Entwurf (Claude) vom 2026-10-14 auf Wunsch von Andi Neck; keine fachliche Prüfung erfolgt.
"""
import json
import re
import sys
import pathlib

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
from _lib import D  # noqa: E402

TAGS = ["TAG-JOHN"]
CHAPTERS = {8: "TU-JHN-008-001-059", 9: "TU-JHN-009-001-041", 10: "TU-JHN-010-001-042", 11: "TU-JHN-011-001-057",
            12: "TU-JHN-012-001-050", 13: "TU-JHN-013-001-038", 14: "TU-JHN-014-001-031"}
_UNITS = sorted(p.stem for p in (D / "text-units").rglob("TU-JHN-*.json"))
CTX_READERS = "CTX-JHN-READERS-0095"
CTX_JESUS = "CTX-GALILEE-0030"


def U(ch, v1, v2=None):
    """Kleinste vorhandene Texteinheit, die Kapitel ch, Verse v1–v2 ganz enthält; sonst die Kapiteleinheit."""
    v2 = v2 or v1
    best = None
    for uid in _UNITS:
        m = re.fullmatch(r"TU-JHN-(\d{3})-(\d{3})-(\d{3})", uid)
        if m and int(m[1]) == ch and int(m[2]) <= v1 and int(m[3]) >= v2:
            if best is None or int(m[3]) - int(m[2]) < best[0]:
                best = (int(m[3]) - int(m[2]), uid)
    return best[1] if best else CHAPTERS[ch]


MAC = "Zählung nach den MACULA-Lemmata zum SBLGNT."
MAC_G = "Zellig nach de MACULA-Lemmata zum SBLGNT."
CNTR = ("Handschriftenangaben aus den CNTR-Transkriptionen, maschinell ausgewertet und nicht am Faksimile geprüft; "
        "Schreibweisen der Handschriften (Itazismen, Abkürzungen) sind nicht normalisiert.")
CNTR_G = ("Handschrifte-Aagaabe us de CNTR-Transkriptione, maschinell uusgwärtet und nöd am Faksimile prüeft; "
          "d Schriibwiise vo de Handschrifte (Itazisme, Abchürzige) sind nöd normalisiert.")

